{"file_text":"/**
 * Azure DefaultAzureCredential Authentication Example
 * 
 * This example demonstrates how to authenticate Azure SDK clients using DefaultAzureCredential,
 * which provides a simplified authentication experience across different environments.
 */

// ============================================================================
// 1. REQUIRED NPM PACKAGES
// ============================================================================
// Install these packages:
// npm install @azure/identity @azure/keyvault-secrets

import { DefaultAzureCredential, ChainedTokenCredential } from '@azure/identity';
import { SecretClient } from '@azure/keyvault-secrets';

// ============================================================================
// 2. CREATING AND USING DefaultAzureCredential
// ============================================================================

/**
 * Basic usage: Create a DefaultAzureCredential instance and use it with any Azure SDK client
 */
async function basicExample() {
  // Step 1: Create the credential
  const credential = new DefaultAzureCredential();

  // Step 2: Use it with an Azure SDK client (SecretClient example)
  const keyVaultUrl = "https://your-keyvault-name.vault.azure.net";
  const client = new SecretClient(keyVaultUrl, credential);

  // Step 3: Make API calls - authentication happens automatically
  try {
    const secret = await client.getSecret("my-secret-name");
    console.log(`Secret value: ${secret.value}`);
  } catch (error) {
    console.error("Error retrieving secret:", error);
  }
}

// ============================================================================
// 3. CREDENTIAL CHAIN ORDER
// ============================================================================
/**
 * DefaultAzureCredential attempts credentials in this order:
 * 
 * 1. EnvironmentCredential
 *    - Checks for environment variables:
 *      AZURE_TENANT_ID, AZURE_CLIENT_ID, AZURE_CLIENT_SECRET (Service Principal)
 *      or AZURE_CLIENT_ID, AZURE_CLIENT_CERTIFICATE_PATH (Certificate-based)
 *      or AZURE_CLIENT_ID, AZURE_USERNAME, AZURE_PASSWORD (Username/Password)
 * 
 * 2. WorkloadIdentityCredential
 *    - For Azure Kubernetes Service (AKS) workload identity
 *    - Checks AZURE_FEDERATED_TOKEN_FILE, AZURE_TENANT_ID, AZURE_CLIENT_ID
 * 
 * 3. ManagedIdentityCredential
 *    - For Azure-hosted resources (VMs, App Service, Functions, AKS, etc.)
 *    - Uses system-assigned or user-assigned managed identity
 *    - No credentials needed - automatically available in Azure
 * 
 * 4. AzureCliCredential
 *    - Uses the Azure CLI's logged-in account
 *    - Run: az login
 *    - Requires Azure CLI installed
 * 
 * 5. AzurePowerShellCredential
 *    - Uses Azure PowerShell's logged-in account
 *    - Run: Connect-AzAccount
 *    - Requires Azure PowerShell module installed
 * 
 * 6. AzureDeveloperCliCredential
 *    - Uses Azure Developer CLI's logged-in account
 *    - Run: azd auth login
 *    - Requires Azure Developer CLI installed
 * 
 * The first credential that succeeds is used. If all fail, an error is thrown.
 */

// ============================================================================
// 4. LOCAL DEV vs AZURE-HOSTED ENVIRONMENTS
// ============================================================================

/**
 * LOCAL DEVELOPMENT (VS Code, Local Machine):
 * - Most commonly uses AzureCliCredential
 * - Developers run: az login
 * - Or use Visual Studio Code Azure Account extension
 * - Or set environment variables for Service Principal
 * 
 * AZURE-HOSTED ENVIRONMENTS (App Service, Functions, VMs, AKS):
 * - Most commonly uses ManagedIdentityCredential
 * - Enable Managed Identity in Azure portal
 * - No code changes needed - same DefaultAzureCredential works
 * - No secrets to manage or rotate
 * 
 * CI/CD PIPELINES (GitHub Actions, Azure DevOps):
 * - Typically uses EnvironmentCredential with Service Principal
 * - Set secrets in pipeline configuration
 * - Or use Workload Identity Federation (recommended, no secrets)
 */

async function environmentAwareExample() {
  const credential = new DefaultAzureCredential();

  // You can optionally configure logging to see which credential is used
  const credentialWithLogging = new DefaultAzureCredential({
    loggingOptions: {
      logLevel: 'info'
    }
  });

  // The same code works everywhere - no environment detection needed!
  const keyVaultUrl = process.env.KEY_VAULT_URL || "https://your-keyvault-name.vault.azure.net";
  const client = new SecretClient(keyVaultUrl, credential);

  return client;
}

// ============================================================================
// 5. TROUBLESHOOTING AUTHENTICATION FAILURES
// ============================================================================

/**
 * Enable detailed logging to diagnose authentication issues
 */
async function troubleshootingExample() {
  // Enable logging to see which credentials are attempted
  const credential = new DefaultAzureCredential({
    loggingOptions: {
      logLevel: 'verbose', // or 'info', 'warning', 'error'
      allowLoggingAccountIdentifiers: true
    }
  });

  try {
    const keyVaultUrl = "https://your-keyvault-name.vault.azure.net";
    const client = new SecretClient(keyVaultUrl, credential);
    const secret = await client.getSecret("test-secret");
    console.log("Authentication successful!");
  } catch (error: any) {
    console.error("Authentication failed!");
    console.error("Error name:", error.name);
    console.error("Error message:", error.message);
    console.error("Error code:", error.code);

    // Common error codes:
    // - CredentialUnavailableError: No credentials in the chain succeeded
    // - ENOENT: Azure CLI not installed or not logged in
    // - AADSTS*: Azure AD authentication errors

    console.error("\nTroubleshooting steps:");
    console.error("1. For local dev: Run 'az login' to authenticate with Azure CLI");
    console.error("2. For Azure-hosted: Enable Managed Identity on your resource");
    console.error("3. Check environment variables (AZURE_TENANT_ID, AZURE_CLIENT_ID, etc.)");
    console.error("4. Verify resource permissions (RBAC roles assigned)");
    console.error("5. Check firewall rules on target resource (Key Vault, Storage, etc.)");
  }
}

/**
 * Common troubleshooting checklist:
 * 
 * LOCAL DEVELOPMENT:
 * ✓ Is Azure CLI installed? (az --version)
 * ✓ Are you logged in? (az login)
 * ✓ Is the correct subscription set? (az account show)
 * ✓ Do you have permissions on the resource? (check Azure RBAC)
 * 
 * AZURE-HOSTED:
 * ✓ Is Managed Identity enabled on the resource?
 * ✓ Does the Managed Identity have the right RBAC role?
 * ✓ Is the Key Vault URL correct?
 * ✓ Are there network restrictions (firewall, private endpoints)?
 * 
 * ENVIRONMENT VARIABLES:
 * ✓ Are all required variables set? (AZURE_TENANT_ID, AZURE_CLIENT_ID, AZURE_CLIENT_SECRET)
 * ✓ Are the values correct? (no extra spaces, quotes, etc.)
 * ✓ Is the Service Principal valid and has permissions?
 */

// ============================================================================
// ADVANCED: CUSTOMIZING THE CREDENTIAL CHAIN
// ============================================================================

/**
 * You can customize which credentials to try and in what order
 */
async function customChainExample() {
  // Option 1: Exclude certain credentials
  const credential = new DefaultAzureCredential({
    excludeEnvironmentCredential: false,
    excludeManagedIdentityCredential: false,
    excludeAzureCliCredential: false,
    excludeAzurePowerShellCredential: true, // Skip PowerShell
    excludeAzureDeveloperCliCredential: true, // Skip azd
    excludeWorkloadIdentityCredential: false
  });

  // Option 2: Specify managed identity client ID (for user-assigned identity)
  const userAssignedCredential = new DefaultAzureCredential({
    managedIdentityClientId: "your-user-assigned-identity-client-id"
  });

  // Option 3: Set timeout for each credential attempt
  const fastFailCredential = new DefaultAzureCredential({
    authorityHost: "https://login.microsoftonline.com",
    // Each credential in the chain will timeout faster
  });

  return credential;
}

// ============================================================================
// COMPLETE WORKING EXAMPLE
// ============================================================================

/**
 * Complete example: Retrieve a secret from Azure Key Vault
 */
async function completeExample() {
  console.log("=== Azure DefaultAzureCredential Example ===\n");

  // 1. Create credential (works in all environments)
  console.log("Creating DefaultAzureCredential...");
  const credential = new DefaultAzureCredential({
    loggingOptions: {
      logLevel: 'info'
    }
  });

  // 2. Configure Key Vault client
  const keyVaultUrl = process.env.KEY_VAULT_URL;
  if (!keyVaultUrl) {
    throw new Error("KEY_VAULT_URL environment variable not set");
  }

  console.log(`Connecting to Key Vault: ${keyVaultUrl}`);
  const secretClient = new SecretClient(keyVaultUrl, credential);

  // 3. Retrieve a secret
  const secretName = "my-secret";
  try {
    console.log(`Retrieving secret: ${secretName}`);
    const secret = await secretClient.getSecret(secretName);
    console.log(`✓ Secret retrieved successfully`);
    console.log(`  Name: ${secret.name}`);
    console.log(`  Value: ${secret.value?.substring(0, 10)}...`); // Show first 10 chars
    console.log(`  Enabled: ${secret.properties.enabled}`);
    console.log(`  Created: ${secret.properties.createdOn}`);
  } catch (error: any) {
    console.error(`✗ Failed to retrieve secret: ${error.message}`);
    throw error;
  }

  // 4. List all secrets
  console.log("\nListing all secrets...");
  try {
    let count = 0;
    for await (const secretProperties of secretClient.listPropertiesOfSecrets()) {
      count++;
      console.log(`  - ${secretProperties.name}`);
    }
    console.log(`✓ Found ${count} secrets`);
  } catch (error: any) {
    console.error(`✗ Failed to list secrets: ${error.message}`);
  }
}

// ============================================================================
// USAGE INSTRUCTIONS
// ============================================================================

/**
 * TO RUN THIS EXAMPLE:
 * 
 * 1. Install dependencies:
 *    npm install @azure/identity @azure/keyvault-secrets typescript ts-node @types/node
 * 
 * 2. FOR LOCAL DEVELOPMENT:
 *    a. Install Azure CLI: https://docs.microsoft.com/cli/azure/install-azure-cli
 *    b. Login: az login
 *    c. Set environment variable: export KEY_VAULT_URL="https://your-keyvault.vault.azure.net"
 *    d. Grant yourself permissions:
 *       az keyvault set-policy --name your-keyvault --upn your@email.com --secret-permissions get list
 * 
 * 3. FOR AZURE-HOSTED (App Service, Functions, etc.):
 *    a. Enable Managed Identity in Azure portal
 *    b. Grant the Managed Identity permissions on Key Vault:
 *       az keyvault set-policy --name your-keyvault --object-id <managed-identity-object-id> --secret-permissions get list
 *    c. Set application setting: KEY_VAULT_URL="https://your-keyvault.vault.azure.net"
 * 
 * 4. FOR CI/CD (Service Principal):
 *    a. Create Service Principal: az ad sp create-for-rbac --name my-app
 *    b. Set environment variables (in GitHub Secrets, Azure DevOps, etc.):
 *       AZURE_TENANT_ID="..."
 *       AZURE_CLIENT_ID="..."
 *       AZURE_CLIENT_SECRET="..."
 *       KEY_VAULT_URL="https://your-keyvault.vault.azure.net"
 *    c. Grant the Service Principal permissions on Key Vault
 * 
 * 5. Run:
 *    npx ts-node azure-default-credential-example.ts
 */

// Run the example if this file is executed directly
if (require.main === module) {
  completeExample()
    .then(() => {
      console.log("\n✓ Example completed successfully");
      process.exit(0);
    })
    .catch((error) => {
      console.error("\n✗ Example failed:", error.message);
      process.exit(1);
    });
}

export {
  basicExample,
  environmentAwareExample,
  troubleshootingExample,
  customChainExample,
  completeExample
};
